describeIf(DIST_EXISTS)('dist directory structure', () => {
  it('dist/index.html exists', () => {
    expect(existsSync(path.join(DIST_DIR, 'index.html'))).toBe(true);
  });

  it('dist/assets directory exists with JS chunks', () => {
    const assetsDir = path.join(DIST_DIR, 'assets');
    expect(existsSync(assetsDir)).toBe(true);
    const files = readdirSync(assetsDir).filter(f => f.endsWith('.js'));
    expect(files.length).toBeGreaterThan(0);
  });

  it('dist/assets has a PDF worker file', () => {
    const assetsDir = path.join(DIST_DIR, 'assets');
    const files = readdirSync(assetsDir);
    const workerFiles = files.filter(f => f.includes('pdf.worker'));
    expect(workerFiles.length).toBeGreaterThan(0);
    expect(workerFiles[0]).toMatch(/\.mjs$/);
  });

  it('main bundle starts with OffReader patch header in pdf.mjs', () => {
    const assetsDir = path.join(DIST_DIR, 'assets');
    const files = readdirSync(assetsDir);
    const pdfWorkerFile = files.find(f => f.includes('pdf.worker') && f.endsWith('.mjs'));
    expect(pdfWorkerFile).toBeTruthy();
    const content = readFileSync(path.join(assetsDir, pdfWorkerFile!), 'utf-8');
    expect(content).toContain('// -- OffReader patch:');
    expect(content).toContain('bytesToHex');
  });
});

